// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address _baseToken, address _nft) public {
        vm.assume(_baseToken != _nft);
        vm.prank(address(this));
        c.initialize(_baseToken, _nft, 100, 100, 0, 100, bytes32(0), false, false);
        assertEq(c.nft(), _nft, "nft should be set to _nft argument");
    }
}
